def start_withp(words):
    result = []
    for item in words:
        # Split string into individual words and check each
        parts = item.split()
        for word in parts:
            if word.lower().startswith('p'):
                result.append(word)
            if len(result) == 2:
                return tuple(result)
    return tuple(result)

# Test case
assert start_withp(["Python PHP", "Java JavaScript", "c c++"]) == ('Python', 'PHP')
```

